// splitting.go — how a closed point splits under a constant extension. A
// closed point of degree d has nat_gcd(d, r) closed points above it on the
// extended curve, each of degree d / nat_gcd(d, r): an ideal of the overlap is
// generated by its part in the chart, a closed point above P is read from its
// first component, and the maximal ideals of the extended chart over fst(P) are
// counted by their l-points.

package curve_point_count

import (
	"github.com/euc-ai/xugo/ext/on"
	. "github.com/euc-ai/xugo/library/authoring"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/constant_field_extension"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/constant_galois"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/constant_splitting"
	"github.com/euc-ai/xugo/library/proofs/algebra/field/field"
	"github.com/euc-ai/xugo/library/proofs/algebra/module/module_record"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/comm_ring"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_away"
	"github.com/euc-ai/xugo/library/proofs/algebra/ring/ring_ideal"
	"github.com/euc-ai/xugo/library/proofs/cartesian/pairs"
	"github.com/euc-ai/xugo/library/proofs/scheme/biaffine_rational_point"
	"github.com/euc-ai/xugo/library/proofs/scheme/closed_divisor"
	"github.com/euc-ai/xugo/library/proofs/scheme/smooth_curve"
	"github.com/euc-ai/xugo/library/proofs/sets/cardinality"
	"github.com/euc-ai/xugo/library/proofs/sets/functions"
	"github.com/euc-ai/xugo/library/proofs/sets/set_basic"
	"github.com/euc-ai/xugo/library/proofs/sets/set_image"
	"github.com/euc-ai/xugo/library/proofs/sets/set_order"
	"github.com/euc-ai/xugo/library/registry"
)

// OverlapIdealGenerated — an ideal J of the overlap of a curve is generated by
// its part in the chart A₀: a power of t clears an element of J into that part,
// and the inverse power, which lies in the overlap, brings it back.
var OverlapIdealGenerated = overlapIdealGeneratedThm{family.Add(registry.ProofEntry{
	Name: "OverlapIdealGenerated",
	Key:  "prop_d659d1532faf2c75",
	Build: family.Theorem(Statement{
		Binders:    "∀M:field_on(A). ∀K k A₀ A₁ A₀₁:set(A). ∀t:A. ∀J:set(A).",
		Hypotheses: []string{"subfield(M, K)", "«ambientCurve»", "ring_ideal(«overlap», J)"},
		Conclusion: "ideal_span(«overlap», A₀ ∩ J) = J",
		Abbrev: Abbrev{
			{Name: "overlap", Text: "restrict_ring(field_ring(M), A₀₁)"},
			{Name: "tPow", Text: "λj:num. monoid_pow(M.mul, M.one, t, j)"},
			{Name: "sPow", Text: "λj:num. monoid_pow(M.mul, M.one, M.inv(t), j)"},
		},
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			K, k, A0, A1, A01 *Expr[Set[A]],
			t *Expr[A],
			J *Expr[Set[A]],
			inField, curve, ideal Fact,
		) {
			ring := a.TermAs[RingOps[A]]("field_ring(M)")
			overlap := a.TermAs[RingOps[A]]("«overlap»")
			part := a.TermAs[Set[A]]("A₀ ∩ J")
			span := a.TermAs[Set[A]]("ideal_span(«overlap», A₀ ∩ J)")
			datum := a.Conjuncts(
				GroupPremises(inField, curve, CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t)),
				"k is a subfield of M",
				"it lies in the chart",
				"the chart is a subring of M",
				"the overlap is a subring of M",
				"the overlap is a ring",
				"it contains the chart",
				"the chart holds t",
				"t is nonzero",
				"the overlap holds the inverse of t",
				"they multiply to one",
				"the overlap is the chart with t inverted, inside itself",
				"and inside M",
				"the powers of t and of its inverse",
				"the curve is a curve in the inverse of t")
			overlapRing, above, away, powers := datum[4], datum[5], datum[11], datum[12]
			inOverlap := a.Have(
				"J lies in the overlap",
				"J ⊆ A₀₁",
				By(ideal, ring_ideal.IdealSubset.At(overlap, J)))
			spanData := a.Have(
				"the span of the part of J in the chart is an ideal holding that part",
				"ring_ideal(«overlap», ideal_span(«overlap», A₀ ∩ J)) ∧ A₀ ∩ J ⊆ ideal_span(«overlap», A₀ ∩ J)",
				By(
					inOverlap,
					ring_ideal.SpanIdeal.Read(overlapRing).At(part),
					ring_ideal.SpanContains.At(overlap, part),
					set_order.SubsetTrans,
					set_order.InterSubset.At(J, A0)))
			inSpan := a.Have(
				"every element of J lies in that span",
				"∀w:A. w ∈ J ⇒ w ∈ ideal_span(«overlap», A₀ ∩ J)",
				Derive(func(b *Argument) {
					w := b.FixAs[A]()
					inJ := b.Assume()
					wIn := b.Have(
						"w lies in the overlap",
						"w ∈ A₀₁",
						By(inOverlap, inJ, set_basic.SubsetDef))
					j, cleared := b.ObtainAs[Nat](
						"a power of t clears w into the chart",
						"∃j:num. «tPow»(j) * w ∈ A₀",
						BySets(wIn, away, ring_away.RingAwayDef.At(ring, A0, t)))
					unit := b.Conjuncts(
						powers.At(j),
						"the power of t lies in the chart",
						"the power of the inverse lies in the overlap",
						"the two invert each other")
					power := b.TermAs[A]("«tPow»(j)")
					back := b.TermAs[A]("«sPow»(j)")
					powerIn := b.Have(
						"so the power of t lies in the overlap",
						"«tPow»(j) ∈ A₀₁",
						BySets(unit[0], above))
					restored := b.Have(
						"multiplying by the inverse power restores w",
						"w = «sPow»(j) * («tPow»(j) * w)",
						ByArith(overlapRing, Scaled(w, unit[2]), wIn, powerIn, unit[1]))
					clearedJ := b.Have(
						"the cleared element lies in J",
						"«tPow»(j) * w ∈ J",
						By(ideal, powerIn, inJ, ring_ideal.IdealMul.At(overlap, J, power, w)))
					clearedSpan := b.Have(
						"so it lies in the span",
						"«tPow»(j) * w ∈ ideal_span(«overlap», A₀ ∩ J)",
						BySets(spanData, clearedJ, cleared))
					b.Show(
						"and so does w, its multiple by the inverse power",
						By(
							Normalized,
							spanData,
							restored,
							unit[1],
							clearedSpan,
							ring_ideal.IdealMul.At(overlap, span, back, b.TermAs[A]("«tPow»(j) * w"))))
				}))
			JInSpan := a.Have(
				"J lies in the span",
				"J ⊆ ideal_span(«overlap», A₀ ∩ J)",
				By(inSpan, set_basic.SubsetDef))
			a.Show(
				"the span lies in J, being the least ideal holding the part, and holds J",
				By(
					ideal,
					JInSpan,
					ring_ideal.SpanLeast.At(overlap, part, J),
					set_order.SubsetAntisym,
					set_order.InterSubset.At(J, A0)))
		}),
})}

// ClosedPointLiesOver — for curves with the same coordinate t and charts
// A ⊆ B, a closed point Q of the larger with fst(Q) over fst(P), P a closed
// point of the smaller, has snd(Q) over snd(P). Both first components hold t or
// neither does. If they do, both second components are whole. If not, both
// second components are read off the extensions to the overlaps, and the
// extension of fst(Q) contracts to the extension of fst(P).
var ClosedPointLiesOver = closedPointLiesOverThm{family.Add(registry.ProofEntry{
	Name: "ClosedPointLiesOver",
	Key:  "prop_416ac4cd36b1041c",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "overlap", Text: "restrict_ring(field_ring(M), A₀₁)"},
			{Name: "bigOverlap", Text: "restrict_ring(field_ring(M), B₀₁)"},
			{Name: "extended", Text: "ideal_span(«bigOverlap», fst(Q))"},
		},
		Binders: "∀M:field_on(A). ∀K L k l A₀ A₁ A₀₁ B₀ B₁ B₀₁:set(A). ∀t:A. ∀P Q:prod(set(A), set(A)).",
		Hypotheses: []string{
			"subfield(M, K)",
			"«ambientCurve»",
			"subfield(M, L)",
			"smooth_finite_curve(restrict_field(M, L), l, t, B₀, B₁, B₀₁)",
			"A₀ ⊆ B₀",
			"A₁ ⊆ B₁",
			"A₀₁ ⊆ B₀₁",
			"«ambientPoint»(P)",
			"curve_closed_point(restrict_ring(field_ring(M), L), B₀, B₁, B₀₁, Q)",
			"fst(P) ≠ A₀",
			"fst(Q) ≠ B₀",
			"A₀ ∩ fst(Q) = fst(P)",
		},
		Conclusion: "A₁ ∩ snd(Q) = snd(P)",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			K, L, k, l, A0, A1, A01, B0, B1, B01 *Expr[Set[A]],
			t *Expr[A],
			P, Q *Expr[Prod[Set[A], Set[A]]],
			inField, curve, bigField, bigCurve, in0, in1, in01, point, bigPoint, properP, properQ, lying Fact,
		) {
			functionField := a.Have(
				"K is a field under M's operations",
				"field_on(restrict_field(M, K))",
				By(inField, field.SubfieldFieldOn.Read(M).At(K)))
			bigFunctionField := a.Have(
				"so is L",
				"field_on(restrict_field(M, L))",
				By(bigField, field.SubfieldFieldOn.Read(M).At(L)))
			extended := a.TermAs[Set[A]]("«extended»")
			inverse := a.TermAs[A]("M.inv(t)")
			first := a.TermAs[Set[A]]("fst(Q)")
			chartP := a.Have(
				"snd(P) is whole exactly when t lies in fst(P)",
				"(snd(P) = A₁ ⇒ t ∈ fst(P)) ∧ (snd(P) ≠ A₁ ⇒ t ∉ fst(P))",
				By(
					curve,
					point,
					properP,
					a.Simplified(
						smooth_curve.ClosedPointChart.Read(functionField).At(k, A0, A1, A01, t, P),
						InAmbient)))
			chartQ := a.Have(
				"snd(Q) is whole exactly when t lies in fst(Q)",
				"(snd(Q) = B₁ ⇒ t ∈ fst(Q)) ∧ (snd(Q) ≠ B₁ ⇒ t ∉ fst(Q))",
				By(
					bigCurve,
					bigPoint,
					properQ,
					a.Simplified(
						smooth_curve.ClosedPointChart.Read(bigFunctionField).At(l, B0, B1, B01, t, Q),
						InAmbient)))
			inChart := a.Have(
				"t lies in the chart",
				"t ∈ A₀",
				By(inField, curve, CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t)))
			a.Cases(a.Term("t ∈ fst(Q)"))
			a.When(
				"t lies in both, so both second components are whole",
				func(b *Argument, holds Fact) {
					inP := b.Have(
						"t lies in fst(P)",
						"t ∈ fst(P)",
						BySets(lying, inChart, holds))
					whole := b.Have(
						"both second components are whole",
						"snd(Q) = B₁ ∧ snd(P) = A₁",
						By(Normalized, chartP, chartQ, holds, inP))
					b.Show(
						"and A₁ lies in B₁",
						BySets(whole, in1))
				})
			a.Otherwise(
				"t lies in neither, so both are read off the overlaps",
				func(b *Argument, misses Fact) {
					outP := b.Have(
						"t misses fst(P)",
						"t ∉ fst(P)",
						BySets(lying, misses))
					bothProper := b.Have(
						"neither second component is whole",
						"snd(Q) ≠ B₁ ∧ snd(P) ≠ A₁",
						By(Normalized, chartP, chartQ, misses, outP))
					proper := b.Conjuncts(
						bothProper,
						"snd(Q) is proper",
						"snd(P) is proper")
					contractedP := b.Have(
						"snd(P) is A₁ in the extension of fst(P)",
						"snd(P) = A₁ ∩ ideal_span(«overlap», fst(P))",
						By(
							curve,
							point,
							properP,
							proper[1],
							b.Simplified(
								smooth_curve.ClosedPointContraction.Read(functionField).At(k, A0, A1, A01, t, P),
								InAmbient)))
					contractedQ := b.Have(
						"snd(Q) is B₁ in the extension of fst(Q)",
						"snd(Q) = B₁ ∩ «extended»",
						By(
							bigCurve,
							bigPoint,
							properQ,
							proper[0],
							b.Simplified(
								smooth_curve.ClosedPointContraction.Read(bigFunctionField).At(l, B0, B1, B01, t, Q),
								InAmbient)))
					maximal := b.Have(
						"fst(Q) is a maximal ideal of B₀",
						"maximal_ideal(restrict_ring(field_ring(M), B₀), fst(Q))",
						By(
							bigPoint,
							properQ,
							smooth_curve.ClosedPointMaximal.At(
								b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), L)"), B0, B1, B01, Q),
							biaffine_rational_point.PointOnChartZero.At(B0, B1, Q),
							module_record.RestrictRingTwice))
					localized := b.Have(
						"it extends to a prime of the overlap of B, contracting back to it",
						"prime_ideal(«bigOverlap», «extended») ∧ B₀ ∩ «extended» = fst(Q)",
						By(
							bigCurve,
							maximal,
							misses,
							b.Simplified(
								smooth_curve.ChartMaximalLocalizes.Read(bigFunctionField).At(l, B0, B1, B01, t, first),
								InAmbient)))
					rings := b.Have(
						"the overlaps are subrings of M, and A₀ lies in the smaller",
						"subring(field_ring(M), A₀₁) ∧ A₀ ⊆ A₀₁ ∧ subring(field_ring(M), B₀₁)",
						By(
							inField,
							curve,
							bigField,
							bigCurve,
							CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t),
							CurveChartsInField.Read(M).At(L, l, B0, B1, B01, t)))
					contraction := b.Have(
						"the extension of fst(Q) meets the smaller overlap in an ideal",
						"ring_ideal(«overlap», A₀₁ ∩ «extended»)",
						By(
							rings,
							in01,
							localized,
							ring_ideal.PrimeIdealIdeal,
							ring_ideal.IdealContraction.At(b.TermAs[RingOps[A]]("field_ring(M)"), A01, B01, extended)))
					meets := b.Have(
						"that ideal meets A₀ in fst(P)",
						"A₀ ∩ (A₀₁ ∩ «extended») = fst(P)",
						BySets(localized, rings, lying, in0))
					generated := b.Have(
						"so it is the extension of fst(P)",
						"ideal_span(«overlap», fst(P)) = A₀₁ ∩ «extended»",
						By(
							inField,
							curve,
							contraction,
							meets,
							OverlapIdealGenerated.Read(M).At(K, k, A0, A1, A01, t, b.TermAs[Set[A]]("A₀₁ ∩ «extended»"))))
					otherInOverlap := b.Have(
						"A₁ lies in the overlap, reading the curve from its other chart",
						"A₁ ⊆ A₀₁",
						By(
							inField,
							curve,
							CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t),
							CurveChartsInField.Read(M).At(K, k, A1, A0, A01, inverse)))
					b.Show(
						"so A₁ meets snd(Q) in snd(P)",
						BySets(contractedQ, contractedP, generated, otherInOverlap, in1))
				})
		}),
})}

// ClosedPointSplittingAtChart — a closed point P of degree d, proper in the
// chart A₀, has gcd(d, r) closed points of the extended curve above it, each
// proper in the chart over l, of degree d / gcd(d, r) there. The first component
// is a bijection from those points onto the maximal ideals of the extended chart
// over fst(P): a maximal ideal is the first component of one closed point, which
// lies over P.
var ClosedPointSplittingAtChart = closedPointSplittingAtChartThm{family.Add(registry.ProofEntry{
	Name: "ClosedPointSplittingAtChart",
	Key:  "prop_220c015603ac23b",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "constants", Text: "finite_constants(field_ring(M), card(k), r)"},
			{Name: "composite", Text: "constant_composite(M, K, «constants»)"},
			{Name: "chart", Text: "λX:set(A). constant_chart(field_ring(M), «constants», X)"},
			{Name: "extRing", Text: "restrict_ring(field_ring(M), «composite»)"},
			{Name: "extCurve", Text: "smooth_finite_curve(restrict_field(M, «composite»), " +
				"    «constants», " +
				"    t, " +
				"    «chart»(A₀), " +
				"    «chart»(A₁), " +
				"    «chart»(A₀₁))"},
			{Name: "extPoint", Text: "λQ:prod(set(A), set(A)). " +
				"    curve_closed_point(«extRing», «chart»(A₀), «chart»(A₁), «chart»(A₀₁), Q)"},
			{Name: "closedOver", Text: "{Q:prod(set(A), set(A)) | " +
				"    «extPoint»(Q) ∧ (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P}"},
			{Name: "maximal", Text: "λn:set(A). maximal_ideal(restrict_ring(field_ring(M), «chart»(A₀)), n)"},
			{Name: "ideals", Text: "{n:set(A) | «maximal»(n) ∧ n ∩ A₀ = fst(P)}"},
			{Name: "residues", Text: "quotient_module(restrict_module(regular_module(field_ring(M)), A₀), " +
				"    fst(P))"},
			{Name: "degree", Text: "module_dim(restrict_ring(field_ring(M), k), «residues»)"},
			{Name: "gcd", Text: "nat_gcd(«degree», r)"},
			{Name: "index", Text: "λn:set(A). " +
				"    module_dim(restrict_ring(field_ring(M), «constants»), " +
				"        quotient_module(restrict_module(regular_module(field_ring(M)), «chart»(A₀)), n))"},
			{Name: "first", Text: "λQ:prod(set(A), set(A)). fst(Q)"},
		},
		Binders: "∀M:field_on(A). ∀K k A₀ A₁ A₀₁:set(A). ∀t:A. ∀r:num. ∀P:prod(set(A), set(A)).",
		Hypotheses: []string{
			"algebraically_closed_field(M)",
			"subfield(M, K)",
			"«ambientCurve»",
			"0 < r",
			"«ambientPoint»(P)",
			"fst(P) ≠ A₀",
		},
		Conclusion: "has_size(«closedOver», «gcd») ∧ " +
			"(∀Q:prod(set(A), set(A)). " +
			"    Q ∈ «closedOver» ⇒ fst(Q) ≠ «chart»(A₀) ∧ «index»(fst(Q)) * «gcd» = «degree»)",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			K, k, A0, A1, A01 *Expr[Set[A]],
			t *Expr[A],
			r *Expr[Nat],
			P *Expr[Prod[Set[A], Set[A]]],
			closed, inField, curve, positive, point, proper Fact,
		) {
			functionField := a.Have(
				"K is a field under M's operations",
				"field_on(restrict_field(M, K))",
				By(inField, field.SubfieldFieldOn.Read(M).At(K)))
			ops := a.TermAs[FieldOps[A]]("M")
			constants := a.TermAs[Set[A]]("«constants»")
			composite := a.TermAs[Set[A]]("«composite»")
			chart0 := a.TermAs[Set[A]]("«chart»(A₀)")
			chart1 := a.TermAs[Set[A]]("«chart»(A₁)")
			chart01 := a.TermAs[Set[A]]("«chart»(A₀₁)")
			ideal := a.TermAs[Set[A]]("fst(P)")
			closedOver := a.TermAs[Set[Prod[Set[A], Set[A]]]]("«closedOver»")
			ideals := a.TermAs[Set[Set[A]]]("«ideals»")
			first := a.TermAs[Fun[Prod[Set[A], Set[A]], Set[A]]]("«first»")
			gcd := a.TermAs[Nat]("«gcd»")
			regular := a.Have(
				"the function field is regular over k in M",
				"regular_function_field(M, k, K)",
				By(inField, curve, SmoothCurveRegular.Read(M).At(K, k, A0, A1, A01, t)))
			smooth := a.Unfolded(curve, smooth_curve.SmoothFiniteFieldCurveDef)
			finiteK := a.Have(
				"the constants of a smooth curve are finite",
				"finite(k)",
				By(smooth))
			data := a.Have(
				"l is a finite subfield of M holding k, and the composite is a subfield",
				"subfield(M, «constants») ∧ subfield(M, «composite»)",
				By(closed, regular, finiteK, positive, constant_galois.ConstantCompositeData.Read(M).At(K, k, r)))
			chartData := a.Have(
				"the chart A₀ is a subring of M between k and K",
				"subring(field_ring(M), A₀) ∧ A₀ ⊆ K ∧ k ⊆ A₀",
				By(inField, smooth, CurveOverLineChartsInField.Read(M).At(K, k, A0, A1, A01, t)))
			extended := a.Have(
				"the extended datum is a smooth curve",
				"«extCurve»",
				By(
					closed,
					inField,
					curve,
					positive,
					SmoothCurveConstantExtension.Read(M).At(K, k, A0, A1, A01, t, r)))
			maximal := a.Have(
				"fst(P) is a maximal ideal of A₀",
				"maximal_ideal(restrict_ring(field_ring(M), A₀), fst(P))",
				By(
					point,
					proper,
					smooth_curve.ClosedPointMaximal.At(a.TermAs[RingOps[A]]("«ambientRing»"), A0, A1, A01, P),
					biaffine_rational_point.PointOnChartZero.At(A0, A1, P),
					module_record.RestrictRingTwice))
			extendedField := a.Have(
				"the composite is a field under M's operations",
				"field_on(restrict_field(M, «composite»))",
				By(data, field.SubfieldFieldOn.Read(M).At(composite)))
			finiteResidues := a.Have(
				"fst(P) has finite degree over k",
				"finite_dimensional(restrict_ring(field_ring(M), k), «residues»)",
				By(
					curve,
					point,
					proper,
					a.Simplified(
						smooth_curve.ClosedPointResidue.Read(functionField).At(k, A0, A1, A01, t, P),
						InAmbient),
					biaffine_rational_point.PointOnChartZero.At(A0, A1, P)))
			split := a.Have(
				"the maximal ideals of the extended chart over fst(P) number gcd(d, r)",
				"has_size(«ideals», «gcd») ∧ "+
					"(∀n:set(A). «maximal»(n) ∧ n ∩ A₀ = fst(P) ⇒ «index»(n) * «gcd» = «degree»)",
				By(
					closed,
					regular,
					finiteK,
					positive,
					chartData,
					maximal,
					finiteResidues,
					constant_splitting.MaximalIdealSplitting.Read(M).At(K, k, A0, ideal, r)))
			inCarrier := a.Have(
				"the charts and the overlap lie in the carrier of M",
				"A₀ ⊆ M.carrier ∧ A₁ ⊆ M.carrier ∧ A₀₁ ⊆ M.carrier",
				By(
					inField,
					smooth,
					CurveOverLineChartsInField.Read(M).At(K, k, A0, A1, A01, t),
					field.SubfieldSubset.At(ops, K),
					set_order.SubsetTrans))
			inclusions := a.Have(
				"each lies in its extension",
				"A₀ ⊆ «chart»(A₀) ∧ A₁ ⊆ «chart»(A₁) ∧ A₀₁ ⊆ «chart»(A₀₁)",
				By(
					data,
					inCarrier,
					constant_field_extension.ConstantChartSubmodule.Read(M).At(constants, A0),
					constant_field_extension.ConstantChartSubmodule.Read(M).At(constants, A1),
					constant_field_extension.ConstantChartSubmodule.Read(M).At(constants, A01)))
			components := a.Have(
				"a point over P has its components over those of P",
				Statement{
					Binders:    "∀Q:prod(set(A), set(A)).",
					Hypotheses: []string{"Q ∈ «closedOver»"},
					Conclusion: "«extPoint»(Q) ∧ A₀ ∩ fst(Q) = fst(P) ∧ A₁ ∩ snd(Q) = snd(P)",
				},
				Derive(func(b *Argument) {
					b.FixAs[Prod[Set[A], Set[A]]]()
					inOver := b.Assume()
					onFirst := b.TermAs[Set[A]]("A₀ ∩ fst(Q)")
					onSecond := b.TermAs[Set[A]]("A₁ ∩ snd(Q)")
					contractions := b.Have(
						"Q is a closed point whose pair of contractions is P",
						"«extPoint»(Q) ∧ (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P",
						BySets(inOver))
					b.Show(
						"the pair of contractions is P",
						By(Normalized, contractions, pairs.Fst.At(onFirst, onSecond), pairs.Snd.At(onFirst, onSecond)))
				}))
			intoIdeals := a.Have(
				"a point over P is proper in the extended chart, at a maximal ideal over fst(P)",
				Statement{
					Binders:    "∀Q:prod(set(A), set(A)).",
					Hypotheses: []string{"Q ∈ «closedOver»"},
					Conclusion: "fst(Q) ≠ «chart»(A₀) ∧ «maximal»(fst(Q)) ∧ fst(Q) ∩ A₀ = fst(P)",
				},
				Derive(func(b *Argument) {
					Q := b.FixAs[Prod[Set[A], Set[A]]]()
					closedOver := b.Have(
						"Q is a closed point over P",
						"«extPoint»(Q) ∧ A₀ ∩ fst(Q) = fst(P) ∧ A₁ ∩ snd(Q) = snd(P)",
						By(components.At(Q), b.Assume()))
					parts := b.Conjuncts(
						closedOver,
						"Q is a closed point of the extended curve",
						"fst(Q) lies over fst(P)",
						"snd(Q) lies over snd(P)")
					notWhole := b.Have(
						"fst(Q) is not the whole extended chart, as fst(P) is not the whole chart",
						"fst(Q) ≠ «chart»(A₀)",
						BySets(inclusions, parts[1], proper))
					maximalQ := b.Have(
						"fst(Q) is a maximal ideal of the extended chart",
						"«maximal»(fst(Q))",
						By(
							parts[0],
							notWhole,
							smooth_curve.ClosedPointMaximal.At(
								b.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «composite»)"),
								chart0,
								chart1,
								chart01,
								Q),
							biaffine_rational_point.PointOnChartZero.At(chart0, chart1, Q),
							module_record.RestrictRingTwice))
					b.Show(
						"so it is a maximal ideal over fst(P)",
						BySets(notWhole, parts[1], maximalQ))
				}))
			hits := a.Have(
				"a maximal ideal over fst(P) is the first component of a point over P",
				Statement{
					Binders:    "∀n:set(A).",
					Hypotheses: []string{"«maximal»(n)", "n ∩ A₀ = fst(P)"},
					Conclusion: "∃Q:prod(set(A), set(A)). Q ∈ «closedOver» ∧ fst(Q) = n",
				},
				Derive(func(b *Argument) {
					n := b.FixAs[Set[A]]()
					nParts := b.Conjuncts(
						b.Assume(),
						"n is maximal",
						"n lies over fst(P)")
					Q, qData := b.ObtainAs[Prod[Set[A], Set[A]]](
						"n is the first component of a closed point Q",
						"∃Q:prod(set(A), set(A)). «extPoint»(Q) ∧ fst(Q) = n",
						By(
							extended,
							nParts[0],
							b.Simplified(
								smooth_curve.ChartMaximalClosedPoint.Read(extendedField).At(
									constants, chart0, chart1, chart01, t, n),
								InAmbient)))
					qParts := b.Conjuncts(
						qData,
						"Q is a closed point of the extended curve",
						"its first component is n")
					onFirst := b.Have(
						"fst(Q) lies over fst(P)",
						"A₀ ∩ fst(Q) = fst(P)",
						BySets(nParts[1], qParts[1]))
					notWhole := b.Have(
						"fst(Q) is not the whole extended chart",
						"fst(Q) ≠ «chart»(A₀)",
						BySets(inclusions, onFirst, proper))
					onSecond := b.Have(
						"so snd(Q) lies over snd(P)",
						"A₁ ∩ snd(Q) = snd(P)",
						By(
							inField,
							curve,
							data,
							extended,
							inclusions,
							point,
							qParts[0],
							proper,
							notWhole,
							onFirst,
							ClosedPointLiesOver.Read(M).At(
								K, composite, k, constants, A0, A1, A01, chart0, chart1, chart01, t, P, Q)))
					pairOver := b.Have(
						"the pair of its contractions is P",
						"(A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P",
						By(Normalized, onFirst, onSecond, pairs.PairEta.At(P)))
					inOver := b.Have(
						"Q is a point over P",
						"Q ∈ «closedOver»",
						BySets(qParts[0], pairOver))
					b.Take(Q)
					b.Show(
						"with first component n",
						By(inOver, qParts[1]))
				}))
			distinct := a.Have(
				"two points over P with one first component are one",
				"∀x y:prod(set(A), set(A)). x ∈ «closedOver» ∧ y ∈ «closedOver» ∧ fst(x) = fst(y) ⇒ x = y",
				Derive(func(b *Argument) {
					x, y := b.FixAs[Prod[Set[A], Set[A]]](), b.FixAs[Prod[Set[A], Set[A]]]()
					pair := b.Conjuncts(
						b.Assume(),
						"x is a point over P",
						"y is a point over P",
						"they have one first component")
					b.Show(
						"a closed point proper in a chart is determined by that chart",
						By(
							extended,
							components.At(x),
							components.At(y),
							intoIdeals.At(y),
							pair[0],
							pair[1],
							pair[2],
							set_order.SubsetRefl.At(b.TermAs[Set[A]]("fst(y)")),
							b.Simplified(
								closed_divisor.ClosedPointChartBelow.Read(extendedField).At(
									constants, chart0, chart1, chart01, t, x, y),
								InAmbient)))
				}))
			injective := a.Have(
				"so the first component is one-to-one on the points over P",
				"injective_on(«closedOver», «first»)",
				By(distinct, functions.InjectiveOnDef.At(closedOver, first)))
			eachIdeal := a.Have(
				"the first component of a point over P is an ideal over fst(P)",
				"∀Q:prod(set(A), set(A)). Q ∈ «closedOver» ⇒ fst(Q) ∈ «ideals»",
				Derive(func(b *Argument) {
					Q := b.FixAs[Prod[Set[A], Set[A]]]()
					b.Show(
						"the first component of a point over P is maximal, over fst(P)",
						BySets(b.Have(
							"fst(Q) is maximal over fst(P)",
							"fst(Q) ≠ «chart»(A₀) ∧ «maximal»(fst(Q)) ∧ fst(Q) ∩ A₀ = fst(P)",
							By(intoIdeals.At(Q), b.Assume()))))
				}))
			inIdeals := a.Have(
				"the first components are such ideals",
				"image(«first», «closedOver») ⊆ «ideals»",
				By(eachIdeal, set_image.ImageSubsetIff.At(first, closedOver, ideals)))
			eachFirst := a.Have(
				"each ideal is a first component",
				"∀n:set(A). n ∈ «ideals» ⇒ n ∈ image(«first», «closedOver»)",
				Derive(func(b *Argument) {
					n := b.FixAs[Set[A]]()
					parts := b.Have(
						"n is maximal over fst(P)",
						"«maximal»(n) ∧ n ∩ A₀ = fst(P)",
						BySets(b.Assume()))
					Q, qData := b.ObtainAs[Prod[Set[A], Set[A]]](
						"it is the first component of a point Q over P",
						"∃Q:prod(set(A), set(A)). Q ∈ «closedOver» ∧ fst(Q) = n",
						By(hits.At(n), parts))
					b.Show(
						"so n is in the image",
						By(qData, set_image.FunInImage.At(first, closedOver, Q)))
				}))
			allIdeals := a.Have(
				"and every such ideal is one",
				"«ideals» ⊆ image(«first», «closedOver»)",
				By(eachFirst, set_basic.SubsetDef))
			image := a.Have(
				"the first components are exactly the maximal ideals over fst(P)",
				"image(«first», «closedOver») = «ideals»",
				By(inIdeals, allIdeals, set_order.SubsetAntisym))
			size := a.Have(
				"so the points over P number gcd(d, r)",
				"has_size(«closedOver», «gcd»)",
				By(injective, image, split, cardinality.HasSizeImageInjEq.At(first, closedOver, gcd)))
			each := a.Have(
				"each has the degree of its first component",
				Statement{
					Binders:    "∀Q:prod(set(A), set(A)).",
					Hypotheses: []string{"Q ∈ «closedOver»"},
					Conclusion: "fst(Q) ≠ «chart»(A₀) ∧ «index»(fst(Q)) * «gcd» = «degree»",
				},
				Derive(func(b *Argument) {
					Q := b.FixAs[Prod[Set[A], Set[A]]]()
					inOver := b.Assume()
					b.Show(
						"its first component is an ideal over fst(P), proper and of the degree found",
						By(split, intoIdeals.At(Q), inOver))
				}))
			a.Show(
				"the count and the degrees",
				By(size, each))
		}),
})}

// ClosedPointSplitting — a closed point P of degree d has gcd(d, r) closed points
// of the curve extended to the field with q^r elements above it, each of degree
// d / gcd(d, r). P is proper in one of its charts. In A₀ this is the splitting
// at the chart. Otherwise it is the splitting at A₁ on the swapped datum,
// carried back by exchanging the two components of a point.
var ClosedPointSplitting = closedPointSplittingThm{family.Add(registry.ProofEntry{
	Name: "ClosedPointSplitting",
	Key:  "prop_62e22655e6121117",
	Build: family.Theorem(Statement{
		Abbrev: Abbrev{
			{Name: "constants", Text: "finite_constants(field_ring(M), card(k), r)"},
			{Name: "composite", Text: "constant_composite(M, K, «constants»)"},
			{Name: "chart", Text: "λX:set(A). constant_chart(field_ring(M), «constants», X)"},
			{Name: "extRing", Text: "restrict_ring(field_ring(M), «composite»)"},
			{Name: "extCurve", Text: "smooth_finite_curve(restrict_field(M, «composite»), " +
				"    «constants», " +
				"    t, " +
				"    «chart»(A₀), " +
				"    «chart»(A₁), " +
				"    «chart»(A₀₁))"},
			{Name: "extPoint", Text: "λQ:prod(set(A), set(A)). " +
				"    curve_closed_point(«extRing», «chart»(A₀), «chart»(A₁), «chart»(A₀₁), Q)"},
			{Name: "swappedPoint", Text: "λQ:prod(set(A), set(A)). " +
				"    curve_closed_point(«extRing», «chart»(A₁), «chart»(A₀), «chart»(A₀₁), Q)"},
			{Name: "extDegree", Text: "λQ:prod(set(A), set(A)). " +
				"    curve_closed_degree(«extRing», «constants», «chart»(A₀), «chart»(A₁), Q)"},
			{Name: "closedOver", Text: "{Q:prod(set(A), set(A)) | " +
				"    «extPoint»(Q) ∧ (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P}"},
			{Name: "swappedOver", Text: "{Q:prod(set(A), set(A)) | " +
				"    «swappedPoint»(Q) ∧ (A₁ ∩ fst(Q), A₀ ∩ snd(Q)) = (snd(P), fst(P))}"},
			{Name: "gcd", Text: "nat_gcd(«ambientPointDegree»(P), r)"},
			{Name: "local", Text: "λS:set(A). λI:set(A). " +
				"    module_dim(restrict_ring(field_ring(M), k), " +
				"        quotient_module(restrict_module(regular_module(field_ring(M)), S), I))"},
			{Name: "extLocal", Text: "λS:set(A). λI:set(A). " +
				"    module_dim(restrict_ring(field_ring(M), «constants»), " +
				"        quotient_module(restrict_module(regular_module(field_ring(M)), S), I))"},
			{Name: "swap", Text: "λQ:prod(set(A), set(A)). (snd(Q), fst(Q))"},
		},
		Binders: "∀M:field_on(A). ∀K k A₀ A₁ A₀₁:set(A). ∀t:A. ∀r:num. ∀P:prod(set(A), set(A)).",
		Hypotheses: []string{
			"algebraically_closed_field(M)",
			"subfield(M, K)",
			"«ambientCurve»",
			"0 < r",
			"«ambientPoint»(P)",
		},
		Conclusion: "card(«closedOver») = «gcd» ∧ " +
			"(∀Q:prod(set(A), set(A)). " +
			"    «extPoint»(Q) ∧ (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P ⇒ " +
			"    «extDegree»(Q) * «gcd» = «ambientPointDegree»(P))",
	},
		func(
			a *Argument,
			M field.FieldFact[on.M],
			K, k, A0, A1, A01 *Expr[Set[A]],
			t *Expr[A],
			r *Expr[Nat],
			P *Expr[Prod[Set[A], Set[A]]],
			closed, inField, curve, positive, point Fact,
		) {
			ops := a.TermAs[FieldOps[A]]("M")
			constants := a.TermAs[Set[A]]("«constants»")
			composite := a.TermAs[Set[A]]("«composite»")
			chart0 := a.TermAs[Set[A]]("«chart»(A₀)")
			chart1 := a.TermAs[Set[A]]("«chart»(A₁)")
			chart01 := a.TermAs[Set[A]]("«chart»(A₀₁)")
			closedOver := a.TermAs[Set[Prod[Set[A], Set[A]]]]("«closedOver»")
			inDegree := a.Have(
				"the degree of P is that of its proper component",
				"«ambientPointDegree»(P) = «local»(point_chart(A₀, A₁, P), point_ideal(A₀, P))",
				By(smooth_curve.ClosedPointDegreeInField.At(ops, K, k, A0, A1, P)))
			a.Cases(a.Term("fst(P) = A₀"))
			a.Otherwise(
				"P is proper in the chart A₀: this is the splitting at that chart",
				func(b *Argument, proper Fact) {
					degree := b.Have(
						"the degree of P is the degree of fst(P) over k",
						"«ambientPointDegree»(P) = «local»(A₀, fst(P))",
						By(inDegree, proper, biaffine_rational_point.PointOnChartZero.At(A0, A1, P)))
					splitting := b.Have(
						"the splitting at the chart",
						"has_size(«closedOver», nat_gcd(«local»(A₀, fst(P)), r)) ∧ "+
							"(∀Q:prod(set(A), set(A)). "+
							"    Q ∈ «closedOver» ⇒ "+
							"    fst(Q) ≠ «chart»(A₀) ∧ "+
							"    «extLocal»(«chart»(A₀), fst(Q)) * nat_gcd(«local»(A₀, fst(P)), r) = «local»(A₀, fst(P)))",
						By(
							closed,
							inField,
							curve,
							positive,
							point,
							proper,
							ClosedPointSplittingAtChart.Read(M).At(K, k, A0, A1, A01, t, r, P)))
					count := b.Have(
						"the count",
						"card(«closedOver») = «gcd»",
						By(
							splitting,
							degree,
							cardinality.CardOfSized.At(closedOver, b.TermAs[Nat]("nat_gcd(«local»(A₀, fst(P)), r)"))))
					each := b.Have(
						"the degrees",
						Statement{
							Binders:    "∀Q:prod(set(A), set(A)).",
							Hypotheses: []string{"«extPoint»(Q)", "(A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P"},
							Conclusion: "«extDegree»(Q) * «gcd» = «ambientPointDegree»(P)",
						},
						Derive(func(c *Argument) {
							Q := c.FixAs[Prod[Set[A], Set[A]]]()
							onP := c.Assume()
							inOver := c.Have(
								"Q is a point over P",
								"Q ∈ «closedOver»",
								BySets(onP))
							parts := c.Have(
								"Q is proper in the extended chart, of the degree found",
								"fst(Q) ≠ «chart»(A₀) ∧ "+
									"«extLocal»(«chart»(A₀), fst(Q)) * nat_gcd(«local»(A₀, fst(P)), r) = «local»(A₀, fst(P))",
								By(splitting, inOver))
							degreeQ := c.Have(
								"its degree reads at the chart over A₀",
								"«extDegree»(Q) = «extLocal»(«chart»(A₀), fst(Q))",
								By(
									parts,
									smooth_curve.ClosedPointDegreeInField.At(ops, composite, constants, chart0, chart1, Q),
									biaffine_rational_point.PointOnChartZero.At(chart0, chart1, Q)))
							c.Show(
								"so its degree is that of its first component",
								By(parts, degree, degreeQ))
						}))
					b.Show(
						"the count and the degrees",
						By(count, each))
				})
			a.When(
				"P is whole at A₀, so proper at A₁: read the splitting through the swap",
				func(b *Argument, atInfinity Fact) {
					swapped := b.TermAs[Prod[Set[A], Set[A]]]("(snd(P), fst(P))")
					otherCurve := b.Have(
						"the curve read from its other chart",
						"smooth_finite_curve(restrict_field(M, K), k, M.inv(t), A₁, A₀, A₀₁)",
						By(inField, curve, CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t)))
					functionField := b.Have(
						"K is a field under M's operations",
						"field_on(restrict_field(M, K))",
						By(inField, field.SubfieldFieldOn.Read(M).At(K)))
					properOther := b.Have(
						"snd(P) is proper in A₁",
						"snd(P) ≠ A₁",
						By(
							curve,
							point,
							atInfinity,
							b.Simplified(
								closed_divisor.ClosedPointProper.Read(functionField).At(k, A0, A1, A01, t, P),
								InAmbient),
							set_order.SubsetRefl))
					swappedPoint := b.Have(
						"the swapped pair is a closed point of the swapped datum",
						"curve_closed_point(restrict_ring(field_ring(M), K), A₁, A₀, A₀₁, (snd(P), fst(P)))",
						By(point, smooth_curve.ClosedPointSwap.At(b.TermAs[RingOps[A]]("«ambientRing»"), A0, A1, A01, P)))
					onFirst := b.Have(
						"its first component is snd(P)",
						"fst((snd(P), fst(P))) = snd(P)",
						By(pairs.Fst.At(b.TermAs[Set[A]]("snd(P)"), b.TermAs[Set[A]]("fst(P)"))))
					properFirst := b.Have(
						"the first component of the swapped pair is proper in A₁",
						"fst((snd(P), fst(P))) ≠ A₁",
						By(Normalized, onFirst, properOther))
					swappedSplitting := b.Have(
						"the splitting at the chart A₁",
						"has_size(«swappedOver», nat_gcd(«local»(A₁, snd(P)), r)) ∧ "+
							"(∀Q:prod(set(A), set(A)). "+
							"    Q ∈ «swappedOver» ⇒ "+
							"    fst(Q) ≠ «chart»(A₁) ∧ "+
							"    «extLocal»(«chart»(A₁), fst(Q)) * nat_gcd(«local»(A₁, snd(P)), r) = «local»(A₁, snd(P)))",
						By(
							closed,
							inField,
							otherCurve,
							positive,
							swappedPoint,
							onFirst,
							properFirst,
							ClosedPointSplittingAtChart.Read(M).At(K, k, A1, A0, A01, b.TermAs[A]("M.inv(t)"), r, swapped)))
					splitting := b.Conjuncts(
						swappedSplitting,
						"the swapped points number gcd(d, r)",
						"each of the degree found")
					swap := b.Have(
						"exchanging components exchanges the closed points of the two data",
						"∀Q:prod(set(A), set(A)). «extPoint»(Q) ⇔ «swappedPoint»((snd(Q), fst(Q)))",
						Derive(func(c *Argument) {
							Q := c.FixAs[Prod[Set[A], Set[A]]]()
							c.Show(
								"a pair is a closed point of one datum when its swap is one of the other",
								By(smooth_curve.ClosedPointSwap.At(
									c.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «composite»)"), chart0, chart1, chart01, Q)))
						}))
					twice := b.Have(
						"and it is an involution",
						"∀Q:prod(set(A), set(A)). (snd((snd(Q), fst(Q))), fst((snd(Q), fst(Q)))) = Q",
						By(pairs.Fst, pairs.Snd, pairs.PairEta))
					components := b.Have(
						"a pair lies over P when its components do",
						"∀Q:prod(set(A), set(A)). "+
							"    (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P ⇔ A₀ ∩ fst(Q) = fst(P) ∧ A₁ ∩ snd(Q) = snd(P)",
						Derive(func(c *Argument) {
							c.FixAs[Prod[Set[A], Set[A]]]()
							c.Show(
								"two pairs are equal when their components are",
								By(
									pairs.PairEta.At(P),
									pairs.PairEq.At(
										c.TermAs[Set[A]]("A₀ ∩ fst(Q)"),
										c.TermAs[Set[A]]("A₁ ∩ snd(Q)"),
										c.TermAs[Set[A]]("fst(P)"),
										c.TermAs[Set[A]]("snd(P)"))))
						}))
					forward := b.Have(
						"the swap of a point over P lies over the swapped pair",
						"∀Q:prod(set(A), set(A)). Q ∈ «closedOver» ⇒ (snd(Q), fst(Q)) ∈ «swappedOver»",
						Derive(func(c *Argument) {
							Q := c.FixAs[Prod[Set[A], Set[A]]]()
							inOver := c.Assume()
							parts := c.Have(
								"Q is a closed point whose pair of contractions is P",
								"«extPoint»(Q) ∧ (A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P",
								BySets(inOver))
							swappedParts := c.Have(
								"its swap is a closed point of the swapped datum, its components over those of P",
								"«swappedPoint»((snd(Q), fst(Q))) ∧ A₀ ∩ fst(Q) = fst(P) ∧ A₁ ∩ snd(Q) = snd(P)",
								By(swap.At(Q), components.At(Q), parts))
							onFirst := c.TermAs[Set[A]]("snd(Q)")
							onSecond := c.TermAs[Set[A]]("fst(Q)")
							swappedPair := c.Have(
								"its pair of contractions is the swapped pair",
								"(A₁ ∩ fst((snd(Q), fst(Q))), A₀ ∩ snd((snd(Q), fst(Q)))) = (snd(P), fst(P))",
								By(Normalized, swappedParts, pairs.Fst.At(onFirst, onSecond), pairs.Snd.At(onFirst, onSecond)))
							c.Show(
								"so it lies over the swapped pair",
								BySets(swappedParts, swappedPair))
						}))
					backward := b.Have(
						"the swap of a point over the swapped pair lies over P",
						"∀Q:prod(set(A), set(A)). Q ∈ «swappedOver» ⇒ (snd(Q), fst(Q)) ∈ «closedOver»",
						Derive(func(c *Argument) {
							Q := c.FixAs[Prod[Set[A], Set[A]]]()
							inOver := c.Assume()
							onFirst := c.TermAs[Set[A]]("snd(Q)")
							onSecond := c.TermAs[Set[A]]("fst(Q)")
							first := c.TermAs[Set[A]]("A₁ ∩ fst(Q)")
							second := c.TermAs[Set[A]]("A₀ ∩ snd(Q)")
							swappedParts := c.Have(
								"Q is a closed point whose pair of contractions is the swapped pair",
								"«swappedPoint»(Q) ∧ (A₁ ∩ fst(Q), A₀ ∩ snd(Q)) = (snd(P), fst(P))",
								BySets(inOver))
							parts := c.Have(
								"Q is a closed point of the swapped datum, its components over those of the swapped pair",
								"«swappedPoint»(Q) ∧ A₁ ∩ fst(Q) = snd(P) ∧ A₀ ∩ snd(Q) = fst(P)",
								By(
									swappedParts,
									pairs.PairEq.At(first, second, c.TermAs[Set[A]]("snd(P)"), c.TermAs[Set[A]]("fst(P)"))))
							swappedQ := c.TermAs[Prod[Set[A], Set[A]]]("(snd(Q), fst(Q))")
							swapPoint := c.Have(
								"its swap is a closed point",
								"«extPoint»((snd(Q), fst(Q)))",
								By(swap.At(swappedQ), twice.At(Q), parts))
							swapPair := c.Have(
								"the pair of contractions of the swap is P",
								"(A₀ ∩ fst((snd(Q), fst(Q))), A₁ ∩ snd((snd(Q), fst(Q)))) = P",
								By(
									components.At(swappedQ),
									parts,
									pairs.Fst.At(onFirst, onSecond),
									pairs.Snd.At(onFirst, onSecond)))
							c.Show(
								"its swap is a closed point with pair of contractions P",
								BySets(swapPoint, swapPair))
						}))
					swapMap := b.TermAs[Fun[Prod[Set[A], Set[A]], Prod[Set[A], Set[A]]]]("«swap»")
					swappedSet := b.TermAs[Set[Prod[Set[A], Set[A]]]]("«swappedOver»")
					size := b.TermAs[Nat]("nat_gcd(«local»(A₁, snd(P)), r)")
					carried := b.Have(
						"so the points over P number as many",
						"has_size(«closedOver», nat_gcd(«local»(A₁, snd(P)), r))",
						By(
							forward,
							backward,
							twice,
							splitting[0],
							cardinality.MutualInversesHasSize.At(swappedSet, closedOver, swapMap, swapMap, size)))
					degree := b.Have(
						"the degree of P is the degree of snd(P) over k",
						"«ambientPointDegree»(P) = «local»(A₁, snd(P))",
						By(inDegree, atInfinity, biaffine_rational_point.PointOffChartZero.At(A0, A1, P)))
					count := b.Have(
						"the count",
						"card(«closedOver») = «gcd»",
						By(carried, degree, cardinality.CardOfSized.At(closedOver, size)))
					oneIn := b.Have(
						"one lies in the chart A₀",
						"M.one ∈ A₀",
						By(
							inField,
							curve,
							CurveChartsInField.Read(M).At(K, k, A0, A1, A01, t),
							comm_ring.SubringOne.At(b.TermAs[RingOps[A]]("field_ring(M)"), A0)))
					each := b.Have(
						"the degrees",
						Statement{
							Binders:    "∀Q:prod(set(A), set(A)).",
							Hypotheses: []string{"«extPoint»(Q)", "(A₀ ∩ fst(Q), A₁ ∩ snd(Q)) = P"},
							Conclusion: "«extDegree»(Q) * «gcd» = «ambientPointDegree»(P)",
						},
						Derive(func(c *Argument) {
							Q := c.FixAs[Prod[Set[A], Set[A]]]()
							onP := c.Assume()
							inOver := c.Have(
								"Q is a point over P",
								"Q ∈ «closedOver»",
								BySets(onP))
							swappedQ := c.TermAs[Prod[Set[A], Set[A]]]("(snd(Q), fst(Q))")
							parts := c.Have(
								"the swap of Q is proper in the extended chart of A₁, of the degree found",
								"fst((snd(Q), fst(Q))) ≠ «chart»(A₁) ∧ "+
									"«extLocal»(«chart»(A₁), fst((snd(Q), fst(Q)))) * nat_gcd(«local»(A₁, snd(P)), r) = "+
									"«local»(A₁, snd(P))",
								By(splitting[1].At(swappedQ), forward.At(Q), inOver))
							onContraction := c.Have(
								"fst(Q) meets A₀ in fst(P), which is A₀",
								"A₀ ∩ fst(Q) = fst(P) ∧ A₁ ∩ snd(Q) = snd(P)",
								By(components.At(Q), onP))
							holdsOne := c.Have(
								"so fst(Q) holds one",
								"M.one ∈ fst(Q)",
								BySets(onContraction, atInfinity, oneIn))
							missesOne := c.Have(
								"a proper first component would be a maximal ideal, missing one",
								"fst(Q) ≠ «chart»(A₀) ⇒ M.one ∉ fst(Q)",
								Derive(func(d *Argument) {
									proper := d.Assume()
									maximal := d.Have(
										"fst(Q) is a maximal ideal of the extended chart",
										"maximal_ideal(restrict_ring(field_ring(M), «chart»(A₀)), fst(Q))",
										By(
											onP,
											proper,
											smooth_curve.ClosedPointMaximal.At(
												d.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «composite»)"),
												chart0,
												chart1,
												chart01,
												Q),
											biaffine_rational_point.PointOnChartZero.At(chart0, chart1, Q),
											module_record.RestrictRingTwice))
									d.Show(
										"and a maximal ideal misses one",
										By(
											maximal,
											ring_ideal.MaximalIdealProper.At(
												d.TermAs[RingOps[A]]("restrict_ring(field_ring(M), «chart»(A₀))"),
												d.TermAs[Set[A]]("fst(Q)"))))
								}))
							whole := c.Have(
								"so fst(Q) is the whole extended chart",
								"fst(Q) = «chart»(A₀)",
								By(holdsOne, missesOne))
							degreeQ1 := c.Have(
								"its degree reads at the chart over A₁",
								"«extDegree»(Q) = «extLocal»(«chart»(A₁), snd(Q))",
								By(
									whole,
									smooth_curve.ClosedPointDegreeInField.At(ops, composite, constants, chart0, chart1, Q),
									biaffine_rational_point.PointOffChartZero.At(chart0, chart1, Q)))
							c.Show(
								"so its degree is that of snd(Q)",
								By(parts, degree, pairs.Fst.At(c.TermAs[Set[A]]("snd(Q)"), c.TermAs[Set[A]]("fst(Q)")), degreeQ1))
						}))
					b.Show(
						"the count and the degrees",
						By(count, each))
				})
		}),
})}
